fn linked_list(&mut self, points: &[[f64;2]], clockwise: bool) -> Option<usize> {
    let len = points.len();
    let mut sum = 0.0;
    let mut j = if len > 0 { len - 1 } else { 0 };
    for i in 0..len {
        let p1 = points[i];
        let p2 = points[j];
        sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
        j = i;
    }
    let mut last: Option<usize> = None;
    if clockwise == (sum > 0.0) {
        for i in 0..len {
            last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
        }
    } else {
        let mut i = len;
        while i > 0 {
            i -= 1;
            last = Some(self.insert_node(i as u32, ...));
        }
    }
    if let Some(l) = last {
        let next = self.nodes[l].next;
        if self.equals(l, next) {
            self.remove_node(l);
            last = Some(self.nodes[l].next); // wait, after remove, l.next unchanged; C++: last = last->next after removeNode(last). removeNode doesn't modify node's own pointers. So last->next is still the old next.
        }
    }
    last
}
```

