fn earcut_linked(&mut self, ear: Option<usize>, indices: &mut Vec<u32>, pass: i32) {
    let mut ear = match ear { Some(e) => e, None => return };
    if pass == 0 && self.hashing { self.index_curve(ear); }
    let mut stop = ear;
    while self.nodes[ear].prev != self.nodes[ear].next {
        let prev = self.nodes[ear].prev;
        let next = self.nodes[ear].next;
        let is_ear = if self.hashing { self.is_ear_hashed(ear) } else { self.is_ear(ear) };
        if is_ear {
            indices.push(self.nodes[prev].i);
            indices.push(self.nodes[ear].i);
            indices.push(self.nodes[next].i);
            self.remove_node(ear);
            ear = self.nodes[next].next;
            stop = self.nodes[next].next;
            continue;
        }
        ear = next;
        if ear == stop {
            if pass == 0 {
                let f = self.filter_points(ear, None);
                self.earcut_linked(f, indices, 1);
            } else if pass == 1 {
                let f = self.filter_points(ear, None);
                let e = self.cure_local_intersections(f, indices);
                self.earcut_linked(Some(e), indices, 2);
            } else if pass == 2 {
                self.split_earcut(ear, indices);
            }
            break;
        }
    }
}
