args.content:
//! Pure-Rust reimplementation of the mapbox earcut polygon triangulation
//! algorithm (ear clipping with z-order-curve hashing for large inputs).
//!
//! Nodes live in a slab (`Vec<Node>`) and are linked by index instead of
//! raw pointers. `NIL` plays the role of a null pointer.

pub const NIL: usize = usize::MAX;

#[derive(Clone)]
struct Node {
    i: u32, // index of the point in the source ring
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32, // z-order curve value
    prev_z: usize,
    next_z: usize,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    hashing: bool,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
        }
    }

    /// Triangulate a polygon given as a list of rings (outer ring first,
    /// any subsequent rings are holes). Returns triangle vertex indices.
    pub fn earcut(&mut self, polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
        let mut indices: Vec<u32> = Vec::new();
        if polygon.is_empty() {
            return indices;
        }

        let len = polygon[0].len();

        let mut outer_node: Option<usize> = None;
        if len > 0 {
            outer_node = self.linked_list(&polygon[0], true);
        }

        if polygon.len() > 1 {
            outer_node = self.eliminate_holes(polygon, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = len > 80;
        if self.hashing {
            let mut min_x = polygon[0][0][0];
            let mut min_y = polygon[0][0][1];
            let mut max_x = min_x;
            let mut max_y = min_y;
            for p in &polygon[0][1..] {
                if p[0] < min_x {
                    min_x = p[0];
                }
                if p[1] < min_y {
                    min_y = p[1];
                }
                if p[0] > max_x {
                    max_x = p[0];
                }
                if p[1] > max_y {
                    max_y = p[1];
                }
            }
            // minX, minY and invSize are later used to transform coords into
            // integers for z-order calculation
            self.min_x = min_x;
            self.min_y = min_y;
            self.inv_size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if self.inv_size != 0.0 {
                32767.0 / self.inv_size
            } else {
                0.0
            };
        }

        self.earcut_linked(outer_node, &mut indices, 0);

        indices
    }

    // create a node and optionally link it with previous one (in a circular
    // doubly linked list)
    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let idx = self.nodes.len();
        let mut node = Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        };
        match last {
            None => {
                node.prev = idx;
                node.next = idx;
            }
            Some(l) => {
                node.next = self.nodes[l].next;
                node.prev = l;
                let n = self.nodes[l].next;
                self.nodes[n].prev = idx;
                self.nodes[l].next = idx;
            }
        }
        self.nodes.push(node);
        idx
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let prev_z = self.nodes[p].prev_z;
        let next_z = self.nodes[p].next_z;
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }

    // link every ring into a loop in a doubly-linked order
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let len = points.len();
        let mut sum = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for (i, p1) in points.iter().enumerate() {
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding
        let mut last: Option<usize> = None;
        if clockwise == (sum > 0.0) {
            for (i, p) in points.iter().enumerate() {
                last = Some(self.insert_node(i as u32, p[0], p[1], last));
            }
        } else {
            for i in (0..len).rev() {
                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
            }
        }

        if let Some(l) = last {
            let next = self.nodes[l].next;
            if self.equals(l, next) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }
        last
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: Option<usize>, indices: &mut Vec<u32>, pass: i32) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        // iterate through ears, slicing them one by one
        let mut stop = ear;
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                indices.push(self.nodes[prev].i);
                indices.push(self.nodes[ear].i);
                indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the first vertex leads to faster sifting
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find
            // any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, None);
                    self.earcut_linked(filtered, indices, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let filtered = self.filter_points(ear, None);
                    let cured = self.cure_local_intersections(filtered, indices);
                    self.earcut_linked(Some(cured), indices, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear, indices);
                }
                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != self.nodes[ear].prev {
            if self.point_in_triangle(
                self.nodes[a].x,
                self.nodes[a].y,
                self.nodes[b].x,
                self.nodes[b].y,
                self.nodes[c].x,
                self.nodes[c].y,
                self.nodes[p].x,
                self.nodes[p].y,
            ) && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // triangle bbox
        let min_tx = self.nodes[a]
            .x
            .min(self.nodes[b].x)
            .min(self.nodes[c].x);
        let min_ty = self.nodes[a]
            .y
            .min(self.nodes[b].y)
            .min(self.nodes[c].y);
        let max_tx = self.nodes[a]
            .x
            .max(self.nodes[b].x)
            .max(self.nodes[c].x);
        let max_ty = self.nodes[a]
            .y
            .max(self.nodes[b].y)
            .max(self.nodes[c].y);

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;

        while p != NIL && self.nodes[p].z <= max_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(
                    self.nodes[a].x,
                    self.nodes[a].y,
                    self.nodes[b].x,
                    self.nodes[b].y,
                    self.nodes[c].x,
                    self.nodes[c].y,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;

        while p != NIL && self.nodes[p].z >= min_z {
            if p != self.nodes[ear].prev
                && p != self.nodes[ear].next
                && self.point_in_triangle(
                    self.nodes[a].x,
                    self.nodes[a].y,
                    self.nodes[b].x,
                    self.nodes[b].y,
                    self.nodes[c].x,
                    self.nodes[c].y,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize, indices: &mut Vec<u32>) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            // a self-intersection where edge (v[i-1],v[i]) intersects (v[i+1],v[i+2])
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                indices.push(self.nodes[a].i);
                indices.push(self.nodes[p].i);
                indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                let pn = self.nodes[p].next;
                self.remove_node(pn);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, None)
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize, indices: &mut Vec<u32>) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    a = self.filter_points(a, Some(a_next));
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, Some(c_next));

                    // run earcut on each half
                    self.earcut_linked(Some(a), indices, 0);
                    self.earcut_linked(Some(c), indices, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: usize, end: Option<usize>) -> usize {
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;

            if !self.nodes[p].steiner
                && (self.equals(p, self.nodes[p].next)
                    || self.area(self.nodes[p].prev, p, self.nodes[p].next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }
        end
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn eliminate_holes(
        &mut self,
        polygon: &[Vec<[f64; 2]>],
        outer_node: Option<usize>,
    ) -> Option<usize> {
        let mut queue: Vec<usize> = Vec::new();
        for ring in &polygon[1..] {
            if let Some(list) = self.linked_list(ring, false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        let mut outer_node = outer_node;
        for hole in queue {
            outer_node = self.eliminate_hole(hole, outer_node);
            if let Some(on) = outer_node {
                let on_next = self.nodes[on].next;
                outer_node = Some(self.filter_points(on, Some(on_next)));
            }
        }
        outer_node
    }

    // find a bridge between vertices that connects hole with an outer ring
    // and link it
    fn eliminate_hole(&mut self, hole: usize, outer_node: Option<usize>) -> Option<usize> {
        let mut outer_node = outer_node?;
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return Some(outer_node);
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, Some(br_next));
        let b_next = self.nodes[bridge].next;
        Some(self.filter_points(bridge, Some(b_next)))
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost point to
        // the left; segment's endpoint with lesser x will be potential connection point
        loop {
            if hy <= self.nodes[p].y
                && hy >= self.nodes[self.nodes[p].next].y
                && self.nodes[self.nodes[p].next].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y)
                        * (self.nodes[self.nodes[p].next].x - self.nodes[p].x)
                        / (self.nodes[self.nodes[p].next].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == self.nodes[p].y {
                            return p;
                        }
                        if hy == self.nodes[self.nodes[p].next].y {
                            return self.nodes[p].next;
                        }
                    }
                    m = if self.nodes[p].x < self.nodes[self.nodes[p].next].x {
                        p
                    } else {
                        self.nodes[p].next
                    };
                }
            }
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }
        if hx == qx {
            return m; // hole touches outer segment; pick lower endpoint
        }

        // look for points inside the triangle of hole point, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the point of the minimum angle
        // with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;

        loop {
            if hx >= self.nodes[p].x
                && self.nodes[p].x >= mx
                && hx != self.nodes[p].x
                && self.point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
            {
                let tan = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (self.nodes[p].x > self.nodes[m].x
                                || (self.nodes[p].x == self.nodes[m].x
                                    && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    // whether sector in vertex m contains sector in vertex p in the same
    // coordinates
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                self.nodes[p].z = self.z_order(x, y);
            }
            self.nodes[p].prev_z = self.nodes[p].prev;
            self.nodes[p].next_z = self.nodes[p].next;
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z;
        self.nodes[prev_z].next_z = NIL;
        self.nodes[p].prev_z = NIL;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, mut list: usize) -> usize {
        let mut in_size: usize = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                // merge two lists
                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else if self.nodes[p].z <= self.nodes[q].z {
                        e = p;
                        p = self.nodes[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.nodes[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.nodes[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.nodes[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            self.nodes[tail].next_z = NIL;

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a point lies within a convex triangle
    #[allow(clippy::too_many_arguments)]
    fn point_in_triangle(
        &self,
        ax: f64,
        ay: f64,
        bx: f64,
        by: f64,
        cx: f64,
        cy: f64,
        px: f64,
        py: f64,
    ) -> bool {
        (cx - px) * (ay - py) >= (ax - px) * (cy - py)
            && (ax - px) * (by - py) >= (bx - px) * (ay - py)
            && (bx - px) * (cy - py) >= (cx - px) * (by - py)
    }

    // check if a diagonal between two polygon nodes is valid (lies in
    // polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    // signed area of a triangle
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    // check if two points are equal
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[self.nodes[p].next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[self.nodes[p].next].i != self.nodes[b].i
                && self.intersects(p, self.nodes[p].next, a, b)
            {
                return true;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            if ((self.nodes[p].y > py) != (self.nodes[self.nodes[p].next].y > py))
                && self.nodes[self.nodes[p].next].y != self.nodes[p].y
                && (px < (self.nodes[self.nodes[p].next].x - self.nodes[p].x)
                    * (py - self.nodes[p].y)
                    / (self.nodes[self.nodes[p].next].y - self.nodes[p].y)
                    + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = self.nodes[p].next;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the
    // same ring, it splits polygon into two; if one belongs to the outer ring
    // and another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.insert_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y, None);
        let b2 = self.insert_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y, None);

        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }
}

/// Convenience free function mirroring `mapbox::earcut<N>(polygon)`.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    Earcut::new().earcut(polygon)
}

mod earcut;

use std::f64::consts::PI;

/// C `atoi` semantics: skip leading whitespace, optional sign, then digits;
/// stops at the first non-digit, returns 0 when no digits are present.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_ascii_whitespace() {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.wrapping_mul(10).wrapping_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    (sign.wrapping_mul(value)) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 11;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut gear: Vec<[f64; 2]> = Vec::new();

    for i in 0..n {
        let angle1 = 2.0 * PI * (i as f64) / (n as f64);
        let angle2 = 2.0 * PI * ((i as f64) + 0.5) / (n as f64);

        gear.push([angle1.cos(), angle1.sin()]);
        gear.push([0.7 * angle2.cos(), 0.7 * angle2.sin()]);
    }

    let polygon: Vec<Vec<[f64; 2]>> = vec![gear];

    let indices = earcut::earcut(&polygon);

    let mut out = String::new();
    for idx in indices {
        out.push_str(&idx.to_string());
        out.push(' ');
    }
    print!("{}", out);
}
